-- Boundary Review v6.99.79 — Tier 2 Batch 3: aourednik 3-entity groups (19 groups, 57 entities)
-- Pattern: keep PRIMARY (matching name), replace others with capital-based circle

BEGIN;

-- Helper macro: just inline SQL per entity. Keep primaries with note only.

-- ABBASID CALIPHATE (3): keep 31, fix 480 480km Cairo, 474 400km Aleppo
UPDATE geo_entities SET ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2-abbasid-primary] LEGITIMATE Abbasid polygon. 2 other entities (Tulunids, Hamdanids) erroneously shared this — corrected.' WHERE id = 31;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 480000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 480000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/abbasid-fix] Replaced erroneous Abbasid polygon with 480km circle. Tulunids (868-905) were a semi-autonomous Egyptian dynasty under Abbasid suzerainty, founded by Ahmad ibn Tulun; expanded into Syria + Hejaz; absorbed back into Abbasid Caliphate 905.' WHERE id = 480;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 400000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/abbasid-fix] Replaced erroneous Abbasid polygon with 400km circle. Hamdanids (890-1004) were a Shia Arab dynasty in N Syria + Mosul, often warring against Byzantines + Buyids; peak under Sayf al-Dawla in Aleppo.' WHERE id = 474;

-- ACHAEMENID EMPIRE (3): keep 847 Persepolis, fix 497 + 490 Babylon
UPDATE geo_entities SET ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2-achaemenid-primary] LEGITIMATE Achaemenid polygon. 2 Babylonian entities erroneously shared this — corrected.' WHERE id = 847;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 500000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 500000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/achaemenid-fix] Replaced erroneous Achaemenid polygon with 500km circle. Neo-Babylonian Empire (Chaldean, 626-539 BCE) under Nabopolassar+Nebuchadnezzar II — controlled Mesopotamia + Levant + parts of Arabia; ended with Persian conquest 539 BCE.' WHERE id = 497;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 500000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 500000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.55), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/achaemenid-fix] Replaced erroneous Achaemenid polygon with 500km circle. 𒆳𒆍𒀭𒊏𒆠 = "Kar-duniash" = Babylonian script for Babylonia. Likely duplicate with id=497 (same dates/capital). DUPLICATE candidate.' WHERE id = 490;

-- ANNAM (3): no clear primary, all early N Vietnam dynasties, all ~150km
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 150000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 150000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/annam-fix] Replaced erroneous "Annam" polygon with 150km circle. Nhà Ngô (939-967) was the first Vietnamese dynasty after a millennium of Chinese rule, founded by Ngô Quyền after Battle of Bach Dang River 938.' WHERE id = 877;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 150000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 150000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/annam-fix] Replaced erroneous "Annam" polygon with 150km circle. Nhà Đinh (968-980) was Đinh Bộ Lĩnh dynasty unifying 12 warring lords; first to use name Đại Cồ Việt; capital Hoa Lư.' WHERE id = 878;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 150000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 150000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/annam-fix] Replaced erroneous "Annam" polygon with 150km circle. Nhà Tiền Lê (Early Lê dynasty, 980-1009) founded by Lê Hoàn (Lê Đại Hành), defended against Song China invasion 981; capital Hoa Lư.' WHERE id = 879;

-- BOSNIA (3): keep 663, fix 665 + 584
UPDATE geo_entities SET ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2-bosnia-primary] LEGITIMATE Bosnia polygon. 2 other entities (Zeta, Serbian Despotate) erroneously shared this — corrected.' WHERE id = 663;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 80000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 80000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/bosnia-fix] Replaced erroneous Bosnia polygon with 80km circle. Zeta (Crnojevic principality, 1360-1421→1499) was a Montenegrin principality on Adriatic coast, predecessor of modern Montenegro; resisted Ottomans longest in W Balkans.' WHERE id = 665;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 200000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 200000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.65), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/bosnia-fix] Replaced erroneous Bosnia polygon with 200km circle. Serbian Despotate (Деспотовина Србија, 1402-1459) was successor state to medieval Serbian Empire, last vassal of Ottomans before annexation 1459 (fall of Smederevo).' WHERE id = 584;

-- CHAGATAI KHANATE (3): keep 328, fix 339 (Moghulistan) + 458 (Northern Yuan)
UPDATE geo_entities SET ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2-chagatai-primary] LEGITIMATE Chagatai polygon. 2 successor states erroneously shared this — corrected.' WHERE id = 328;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 600000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 600000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/chagatai-fix] Replaced erroneous Chagatai polygon with 600km circle. مغولستان (Moghulistan, 1347-1462) was the eastern Chagatai successor — Tarim Basin + Yedisu + Issyk Kul + parts of Mongolia; western half (Transoxiana) became Timurid base.' WHERE id = 339;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 900000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 900000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/chagatai-fix] Replaced erroneous Chagatai polygon with 900km circle. 北元 (Northern Yuan, 1368-1635) was the Mongol regime that retreated from China after Yuan fall — covered Mongolia, parts of Manchuria; continued Yuan claim until Ligdan Khan death 1634.' WHERE id = 458;

-- GHAZNAVID EMIRATE (3): keep 143, mark 477 as DUPLICATE, fix 509 (Ghurid)
UPDATE geo_entities SET ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2-ghaznavid-primary] LEGITIMATE Ghaznavid polygon. id=477 is duplicate transliteration; id=509 is successor Ghurid Sultanate — corrected.' WHERE id = 143;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 600000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 600000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.55), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/ghaznavid-fix] Replaced erroneous Ghaznavid polygon with 600km circle. دولت غزنویان is alternate transliteration of "Ghaznavid Empire" — DUPLICATE candidate with id=143 (same dates 977-1186, same capital Ghazni). Recommend merge.' WHERE id = 477;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 600000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 600000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/ghaznavid-fix] Replaced erroneous Ghaznavid polygon with 600km circle. الدولة الغورية (Ghurid Sultanate, 1148-1215) was the Ghaznavid successor — central Afghanistan based at Firuzkuh; Muhammad Ghuri conquered N India after 1192 (Battle of Tarain); collapsed after Muhammad''s death 1206 (Delhi Sultanate fragment).' WHERE id = 509;

-- GOLDEN HORDE (3): all 3 are successors, no clear primary, fix all
UPDATE geo_entities SET
  boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(55.0, 47.0), 4326)::geography, 800000)::geometry)),
  boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(55.0, 47.0), 4326)::geography, 800000)::geometry),
  boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL,
  capital_lat = COALESCE(capital_lat, 47.0), capital_lon = COALESCE(capital_lon, 55.0),
  confidence_score = LEAST(confidence_score, 0.5),
  ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/horde-fix] Replaced erroneous Golden Horde polygon with 800km circle centered at (47°N, 55°E) — approximate center of Kazakh steppe (no fixed nomadic capital). Nogai Horde (Ногай Ордасы, 1390-1634) was a Mangit Tatar confederation between Volga + Irtysh + Caspian, originally part of Golden Horde, broke away under Edigu.'
WHERE id = 338;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 250000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 250000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/horde-fix] Replaced erroneous Golden Horde polygon with 250km circle around Kazan. Kazan Khanate (Казан ханлыгы, 1438-1552) was a successor of Golden Horde in middle Volga (Tatars, Mari, Chuvash); conquered by Ivan IV the Terrible 1552.' WHERE id = 330;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 300000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 300000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/horde-fix] Replaced erroneous Golden Horde polygon with 300km circle around Astrakhan. Astrakhan Khanate (Хаҗитархан ханлыгы, 1466-1556) was the southernmost successor of Golden Horde (lower Volga + Caspian coast); conquered by Ivan IV 1556 completing Russian control of Volga.' WHERE id = 333;

-- HITTITES (3): keep 172, fix 816 + 508
UPDATE geo_entities SET ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2-hittite-primary] LEGITIMATE Hittite Empire polygon (Hattusa-based 1600-1178 BCE). 2 successor/related states erroneously shared this — corrected.' WHERE id = 172;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 150000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 150000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/hittite-fix] Replaced erroneous Hittite polygon with 150km circle around Tarsos. 𐤊𐤋𐤊 = Que / Hiyawa / Adanawa — Iron Age Anatolian Cilician kingdom (1200 BCE - 67 BCE), successor to Hittite Empire; multiple phases (Neo-Hittite Que, Persian satrapy, Hellenistic, Roman annexation 67 BCE).' WHERE id = 816;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 80000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 80000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/hittite-fix] Replaced erroneous Hittite polygon with 80km circle around Carchemish. Karkamış (Carchemish, 1180-717 BCE) was a Neo-Hittite city-kingdom on the upper Euphrates after Bronze Age collapse; absorbed by Assyria 717 BCE under Sargon II.' WHERE id = 508;

