UPDATE geo_entities SET ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2-moche-primary] LEGITIMATE Moche polygon. 2 cultures (Recuay, Gallinazo) erroneously shared this — corrected.' WHERE id = 200;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 80000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 80000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.55), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/moche-fix] Replaced erroneous Moche polygon with 80km circle. Recuay (-200 to 600 CE) was a N Peruvian highland Andean culture contemporary with Moche; capital Pashash in Callejón de Huaylas; known for stonework + ceramics.' WHERE id = 656;
UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 50000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 50000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.55), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/moche-fix] Replaced erroneous Moche polygon with 50km circle. Gallinazo / Virú (-200 to 600 CE) was a coastal Peruvian culture in Virú + Moche valleys, often considered Moche predecessor or contemporary; complex irrigation + ceramics.' WHERE id = 971;

