UPDATE geo_entities SET ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2-olmec-primary] LEGITIMATE Olmec cultural-region polygon. 2 specific sites (San Lorenzo, La Venta) erroneously shared this same polygon — now corrected to site-specific circles.' WHERE id = 191;
