UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 300000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 300000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/pagan-fix] Replaced erroneous Pagan polygon with 300km circle. ဟံသာဝတီ (Hanthawaddy/Pegu, 1287-1539) was a Mon kingdom in Lower Burma after Pagan collapse, capital Bago/Pegu; absorbed by Toungoo 1539.' WHERE id = 690;
