-- PARTHIAN EMPIRE (3): keep 120, fix 624 + 821
UPDATE geo_entities SET ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2-parthian-primary] LEGITIMATE Parthian polygon. 2 vassal kingdoms erroneously shared this — corrected.' WHERE id = 120;
