UPDATE geo_entities SET boundary_geojson = ST_AsGeoJSON(ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 200000)::geometry)), boundary_geom = ST_Multi(ST_Buffer(ST_SetSRID(ST_MakePoint(capital_lon, capital_lat), 4326)::geography, 200000)::geometry), boundary_source = 'approximate_circle', boundary_aourednik_name = NULL, boundary_aourednik_year = NULL, boundary_aourednik_precision = NULL, confidence_score = LEAST(confidence_score, 0.6), ethical_notes = COALESCE(ethical_notes, '') || E'\n\n[v6.99.79-tier2/ur-fix] Replaced erroneous Ur polygon with 200km circle around Babylon. 𒀀𒈬𒊒𒌝 = Amorite Babylonia (Old Babylonian period 2000-1595 BCE), peak under Hammurabi (~1810-1750 BCE) who codified law + conquered Larsa+Eshnunna+Mari; sacked by Hittite raid 1595 BCE.' WHERE id = 619;

